local UIRolePlotDialog = Class("UIRolePlotDialog")

function UIRolePlotDialog:__init() 
    self._curRoleId = nil                 --当前选择的角色id
    self._allChapter = {}                 --所有的章节
end

function UIRolePlotDialog:__delete()
    self._curRoleId = nil                 --当前选择的角色id
    self._allChapter = nil                --所有的章节
end

function UIRolePlotDialog:Awake()
    local argument = self.controller.Argument.parameters
    if argument then
        self._curRoleId = checkNumber(argument.roleId)  --副本类型
    end

    if checkNumber(self._curRoleId) == 0 then
        return
    end

    self:FillSelf()
end

function UIRolePlotDialog:OnShow()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        --[[
        local lastChapterId = roleStoryComp:GetLastChapterId()

        cs_coroutine.start(function()
            coroutine.yield(WaitForSeconds(0.7))
            if checkNumber(lastChapterId) > 0 then
                local ind = CfUtils.GetTableValueKey(self._allChapter, "id", lastChapterId)
                if ind then
                    self.LoopViewChapter:JumpTo(checkNumber(ind) - 1)
                else
                    self.LoopViewChapter:JumpTo(0)
                end
            else
                self.LoopViewChapter:JumpTo(0)
            end
        end)
        ]]


        cs_coroutine.start(function()
            coroutine.yield(WaitForSeconds(0.001))
            self.LoopViewChapter:JumpTo(0)
            coroutine.yield(WaitForSeconds(0.001))

            coroutine.yield(WaitForSeconds(0.1))
            local effectBg = self.controller.gameObject.transform:Find("Root/BgContainer/BG/fuzzy").gameObject:GetComponent(typeof(UIEffectCapturedImage))
            effectBg:Capture()

            local lastChallengeChapterId = checkNumber(KCookie.Get("UIRolePlotDialogLastChallenge"))
            if checkNumber(lastChallengeChapterId) > 0 then
                KCookie.Set("UIRolePlotDialogLastChallenge", 0)
                CS.Engine.UI.UIModule.OpenDialog({id = Constants.UITypeIds.UIPolePlotListDialog, parameters = {id = lastChallengeChapterId}}, {
                    { id = Constants.UITypeIds.UIRolePlotDialog }
                })
            end
        end)
    end))
    return coWait
end

function UIRolePlotDialog:FillSelf()
    SetButtonAction(self.BtnClose, Bind(self, self.OnBtnClose))

    local vo = self:GetRoleInfoVo(self._curRoleId)
    if not vo then
        return
    end
    local roleVo = CardConfMgr:GetInstance():GetRolesByCharacterType(self._curRoleId)
    if roleVo then
        CfUtils.FillText(self.TxtName2, roleVo.englishName)
    end

    CfUtils.FillText(self.TxtName, vo.name)
    CfUtils.FillImage(self.ImgRole, vo.bodyIcon)

    local allChapterId = QuestConfMgr:GetInstance():GetRoleStoryChapterIds(self._curRoleId)
    if not allChapterId then
        return
    end

    self._allChapter = {}
    for k, v in pairs(allChapterId) do
        local vo = QuestConfMgr:GetInstance():GetRoleStoryChapterVo(v)
        table.insert(self._allChapter, vo)
    end
    self.LoopViewChapter:InitListView(table.count(self._allChapter), self._allChapter)
    self.LoopViewChapter.OnIndexChanged = Bind(self, self.OnSelectCell)

    --iOS会不出现背景？ 提前绘制第一个的 
    self:OnSelectCell(0)
end

function UIRolePlotDialog:OnSelectCell(index)
    local vo = self._allChapter[index + 1]
    if vo then
        CfUtils.FillImage(self.controller.gameObject.transform:Find("Root/BgContainer/BG"), vo.sectionIcon)
    end
end

function UIRolePlotDialog:OnBtnClose()
    UIModule.BackDialog()
end

---GetRoleInfoVoConfig 获取一个角色的信息
---@param id string 角色id
function UIRolePlotDialog:GetRoleInfoVo(id)
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting851, "RoleStoryRoleVo", checkString(id))
    return vo
end

